from pathlib import Path
import json
import pandas as pd
R=Path(__file__).resolve().parent;O=R/'outputs';DEST=R.parent/'final_audited'
def records(name):return json.loads(pd.read_csv(O/name).to_json(orient='records'))
data=dict(schema_version=1,cutoff='2026-10-16',processed='2026-10-17',baseline=records('baseline_forecasts.csv'),forecasts=records('forecasts.csv'),media=records('monthly_media.csv'),factual=records('matched_release_cases.csv'),events=[dict(date='2024-04-01',event='Michigan begins gradual phone-to-web transition',type='Survey methodology'),dict(date='2024-07-01',event='Michigan fully web-based collection',type='Survey methodology'),dict(date='2025-01-20',event='US presidential inauguration',type='Political context'),dict(date='2026-10-16',event='Economic cutoff; October sentiment remains preliminary',type='Data cutoff'),dict(date='2026-11-03',event='Scheduled midterm election; future relative to cutoff',type='Prospective event')])
(DEST/'Monitoring_Data.json').write_text(json.dumps(data,indent=2))
html=r'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Consumer sentiment monitor</title><style>
body{font:16px/1.55 system-ui,sans-serif;color:#20384b;background:#f5f7f6;margin:0}main{max-width:1100px;margin:auto;padding:32px}h1{font-size:34px;margin:0 0 12px}h2{margin:28px 0 10px}p{max-width:1000px}label{display:inline-block;margin:8px 20px 8px 0}select,button,input{font:inherit;padding:7px;border:1px solid #91a7ac;border-radius:3px;background:white}button{cursor:pointer}canvas{display:block;width:100%;height:280px;background:white}section{margin:24px 0}.small{font-size:14px;color:#506878}.status{padding:14px;background:#fff0da;border-left:4px solid #b87927}table{width:100%;border-collapse:collapse;background:#fff;font-size:14px}th,td{padding:9px;text-align:left;border-bottom:1px solid #d4dfe0;vertical-align:top}th{background:#e6f0ef}.scroll{max-height:350px;overflow:auto}a{color:#00796d}#error{color:#9e3021;font-weight:600}footer{margin-top:28px;padding:16px 0;border-top:1px solid #c8d5d7}</style>
<main><h1>Economic narratives and consumer sentiment</h1><p id="stamp"></p><p class="status">Exploratory retrospective evaluation with revised inputs and assumed posting lags. AI labels lack the required independent human validation. Missing media stays missing. October 2026 sentiment is preliminary and excluded from scoring.</p>
<label>Show data from <select id="start"><option>2020</option><option>2022</option><option selected>2024</option><option>2025</option><option>2026</option></select></label><label>Economic prediction <select id="model"><option>M1 Economics</option><option>Households</option><option>Dynamic economics</option><option>Dynamic households</option><option>Last month</option></select></label>
<button id="export">Export monitoring JSON</button><label>Import documented JSON <input type="file" id="import" accept="application/json,.json"></label><p id="error" role="alert"></p>
<section><h2>Sentiment and the selected prediction</h2><p id="latest"></p><canvas id="sentiment" aria-label="Sentiment and prediction with nominal 90 percent interval"></canvas><p class="small">Navy: observed. Teal: prediction. Pale teal: nominal 90% prediction interval. Intervals are approximate under dependence.</p></section>
<section><h2>Economic-only sentiment gap</h2><canvas id="gap" aria-label="Observed sentiment minus earlier-data M1 prediction"></canvas><p class="small">Observed minus expanding M1 prediction. A negative gap is a model error, not measured media bias.</p></section>
<section><h2>Original title tone</h2><canvas id="tone" aria-label="Equal-source AI tone with conditional 95 percent title resampling interval"></canvas><p class="small">-1 adverse, 0 mixed/undirected, +1 favorable. Equal outlet weights. Shading reflects conditional title sampling only. It omits coding, archive-selection, and exposure uncertainty. Gaps break the line.</p></section>
<section><h2>Source composition and wording</h2><p class="small">At least three selected titles from each source per valid month. Wording shares refer only to this economic-title sample. Missing topic/framing values do not mean zero.</p><div class="scroll"><table id="coverage"></table></div></section>
<section><h2>Model performance</h2><p class="small">All primary models use identical 21 finalized target months. Long economic results use a separate 81-month sample. The tables below keep those samples separate.</p><table id="accuracy"></table><h3>Long economic evaluation</h3><table id="longaccuracy"></table></section>
<section><h2>Release-calibrated title cases</h2><p class="small">Purposive examples, not a whole-corpus factual-accuracy rate.</p><div class="scroll"><table id="factual"></table></div></section>
<section><h2>Events and data status</h2><table id="events"></table></section>
<footer>Update process: append raw releases and publisher metadata, preserve their dates and vintages, finalize coding, run the Python analysis, then regenerate this dashboard. Import changes the display and recalculates error summaries from supplied forecast records. It does not refit regressions. Freeze new forecasts before their outcomes arrive.</footer></main>
<script>
let data=__DATA__;
const $=id=>document.getElementById(id),finite=x=>typeof x==='number'&&Number.isFinite(x),fmt=x=>finite(x)?x.toFixed(2):'Missing';
function validate(d){if(typeof d.cutoff!=='string'||typeof d.processed!=='string')throw Error('Missing cutoff/processed');if(d.schema_version!==1)throw Error('Unsupported schema_version');for(const k of ['baseline','forecasts','media','factual','events'])if(!Array.isArray(d[k]))throw Error('Missing array: '+k);for(const k of ['baseline','forecasts'])for(const r of d[k]){if(!/^\d{4}-\d{2}-\d{2}/.test(r.period)||typeof r.model!=='string'||!finite(r.actual)||!finite(r.predicted)||typeof r.preliminary!=='boolean')throw Error('Invalid forecast record');}for(const r of d.media){if(!/^\d{4}-\d{2}$/.test(r.month))throw Error('Invalid media month');if(r.tone_score!==null&&(!finite(r.tone_score)||Math.abs(r.tone_score)>1))throw Error('Invalid tone');}return d;}
function table(id,headers,rows){const t=$(id);t.replaceChildren();let tr=document.createElement('tr');for(const h of headers){let x=document.createElement('th');x.textContent=h;tr.append(x);}t.append(tr);for(const row of rows){tr=document.createElement('tr');for(const val of row){let x=document.createElement('td');x.textContent=val===null?'Missing':String(val);tr.append(x);}t.append(tr);}}
function plot(id,rows,fields,band,range){const c=$(id),ctx=c.getContext('2d');c.width=1050;c.height=280;ctx.clearRect(0,0,c.width,c.height);const L=55,R=1015,T=20,B=240;let vals=rows.flatMap(r=>fields.map(f=>r[f])).filter(finite);if(band)vals.push(...rows.flatMap(r=>[r[band[0]],r[band[1]]]).filter(finite));if(!vals.length){ctx.fillText('No observations in this window',60,50);return;}let lo=range?range[0]:Math.min(...vals),hi=range?range[1]:Math.max(...vals);if(hi===lo)hi=lo+1;const Y=v=>B-(v-lo)/(hi-lo)*(B-T),X=i=>L+i*(R-L)/Math.max(1,rows.length-1);ctx.font='13px system-ui';ctx.fillStyle='#506878';for(let i=0;i<=4;i++){let v=lo+(hi-lo)*i/4;ctx.fillText(v.toFixed(1),3,Y(v)+4);ctx.strokeStyle='#e4eaea';ctx.beginPath();ctx.moveTo(L,Y(v));ctx.lineTo(R,Y(v));ctx.stroke();}if(band){ctx.fillStyle='#d2e8e2';for(let i=0;i<rows.length-1;i++){let a=rows[i],b=rows[i+1];if([a[band[0]],a[band[1]],b[band[0]],b[band[1]]].every(finite)){ctx.beginPath();ctx.moveTo(X(i),Y(a[band[0]]));ctx.lineTo(X(i+1),Y(b[band[0]]));ctx.lineTo(X(i+1),Y(b[band[1]]));ctx.lineTo(X(i),Y(a[band[1]]));ctx.closePath();ctx.fill();}}}fields.forEach((f,j)=>{ctx.strokeStyle=['#263e5a','#008577'][j];ctx.lineWidth=2.5;ctx.beginPath();let open=false;rows.forEach((r,i)=>{if(!finite(r[f])){open=false;return;}if(open)ctx.lineTo(X(i),Y(r[f]));else{ctx.moveTo(X(i),Y(r[f]));open=true;}});ctx.stroke();rows.forEach((r,i)=>{if(finite(r[f])){ctx.beginPath();ctx.arc(X(i),Y(r[f]),2.3,0,Math.PI*2);ctx.fillStyle=ctx.strokeStyle;ctx.fill();}});});ctx.fillStyle='#506878';ctx.fillText((rows[0].period||rows[0].month).slice(0,7),L,267);ctx.fillText((rows.at(-1).period||rows.at(-1).month).slice(0,7),R-55,267);}
function accuracy(rows){const models=[...new Set(rows.map(r=>r.model))];return models.map(model=>{const q=rows.filter(r=>r.model===model&&!r.preliminary),errors=q.map(r=>r.actual-r.predicted);return[model,q.length,fmt(Math.sqrt(errors.reduce((a,x)=>a+x*x,0)/q.length)),fmt(errors.reduce((a,x)=>a+Math.abs(x),0)/q.length),fmt(100*q.filter(r=>r.actual>=r.lower90&&r.actual<=r.upper90).length/q.length)+'%'];});}
function render(){const year=$('start').value,model=$('model').value;const b=data.baseline.filter(r=>r.model===model&&r.period.slice(0,4)>=year);const gaps=data.baseline.filter(r=>r.model==='M1 Economics'&&r.period.slice(0,4)>=year);const media=data.media.filter(r=>r.month.slice(0,4)>=year);$('stamp').textContent='Economic cutoff: '+data.cutoff+'. Processing: '+data.processed+'. Selected titles: '+data.media.reduce((n,r)=>n+(r.n_NPR||0)+(r.n_Colorado_Sun||0)+(r.n_Hacker_News||0),0)+' / '+data.media.filter(r=>r.valid_balanced).length+' balanced months.';const last=b.at(-1);$('latest').textContent=last?last.period.slice(0,7)+': observed '+fmt(last.actual)+', prediction '+fmt(last.predicted)+(last.preliminary?' (preliminary outcome).':'.'):'No data.';plot('sentiment',b,['actual','predicted'],['lower90','upper90']);plot('gap',gaps.map(r=>({...r,gap:r.actual-r.predicted})),['gap']);plot('tone',media,['tone_score'],['lower95','upper95'],[-1,1]);table('coverage',['Month','NPR','Colorado Sun','Hacker News','Balanced','Price-level wording','Rate wording','Labor attention'],media.map(r=>[r.month,r.n_NPR,r.n_Colorado_Sun,r.n_Hacker_News,r.valid_balanced?'Yes':'No',finite(r.level_frame)?fmt(100*r.level_frame)+'%':'Missing',finite(r.rate_frame)?fmt(100*r.rate_frame)+'%':'Missing',finite(r.labor)?fmt(100*r.labor)+'%':'Missing']));table('accuracy',['Model','n','RMSE','MAE','90% interval coverage'],accuracy(data.forecasts));table('longaccuracy',['Model','n','RMSE','MAE','90% interval coverage'],accuracy(data.baseline));table('factual',['Event','Title','Official benchmark','Assessment'],data.factual.map(r=>[r.event,r.title,r.official_value,r.assessment]));table('events',['Date','Type','Event'],data.events.map(r=>[r.date,r.type,r.event]));}
$('start').addEventListener('change',render);$('model').addEventListener('change',render);$('export').addEventListener('click',()=>{let blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='Monitoring_Data.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);});$('import').addEventListener('change',async e=>{try{let next=validate(JSON.parse(await e.target.files[0].text()));data=next;$('error').textContent='';render();}catch(err){$('error').textContent=err.message;}});validate(data);render();globalThis.monitorTest={validate,accuracy,render};
</script></html>'''
(DEST/'Monitoring_Dashboard.html').write_text(html.replace('__DATA__',json.dumps(data).replace('</','<\\/')))
print('Dashboard built')
